/*
 * A242912  Finite sequence where each term follows n*10^n + p, where p is an
 *          n-digit prime and 1 <= n <= 9.
 * https://oeis.org/A242912
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini
 * Formula:   a(n) = n*10^n + p * where p is the n‑digit prime that is in
 *            ascending order. * The sequence is generated by enumerating all
 *            primes of each digit * length in order and prefixing them with
 *            n*10^n. * For example: n = 2, p = 19 → 2*10^2 + 19 = 219
 * Range:     u8 n <= 16, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   isPrimeTrial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/isPrimeTrial.h"

static seq_t pow10_arr[10];
static size_t exact_counts[10];   /* primes of exactly d digits, 1 ≤ d ≤ 6 */
static size_t prefix_counts[10];
static uint64_t *primes = NULL;
static size_t primes_count = 0;
static bool init_done = false;

/* Pre‑compute powers of ten and primes up to 10^6 */
static void init(void)
{
    if (init_done) return;
    init_done = true;

    /* powers of ten */
    pow10_arr[0] = (seq_t)1;
    for (int i = 1; i < 10; ++i) {
        pow10_arr[i] = pow10_arr[i - 1] * (seq_t)10;
    }

    /* sieve up to 1,000,000 */
    const idx_t LIMIT = 1000000;
    bool *marked = (bool *)malloc((LIMIT + 1) * sizeof(bool));
    for (idx_t i = 0; i <= LIMIT; ++i) marked[i] = false;

    for (idx_t p = 2; p * p <= LIMIT; ++p) {
        if (!marked[p]) {
            for (idx_t m = p * p; m <= LIMIT; m += p) {
                marked[m] = true;
            }
        }
    }

    /* count primes */
    for (idx_t i = 2; i <= LIMIT; ++i) {
        if (!marked[i]) primes_count++;
    }

    /* store primes */
    primes = (uint64_t *)malloc(primes_count * sizeof(uint64_t));
    size_t idx = 0;
    for (idx_t i = 2; i <= LIMIT; ++i) {
        if (!marked[i]) {
            primes[idx++] = (uint64_t)i;
        }
    }
    free(marked);

    /* prefix counts of primes up to 10^d-1 for d = 1..6 */
    size_t pos = 0;
    prefix_counts[0] = 0;
    for (int d = 1; d <= 6; ++d) {
        while (pos < primes_count && primes[pos] <= (uint64_t)(pow10_arr[d] - 1)) {
            pos++;
        }
        prefix_counts[d] = pos;
    }

    /* exact counts of d‑digit primes */
    for (int d = 1; d <= 6; ++d) {
        exact_counts[d] = prefix_counts[d] - prefix_counts[d - 1];
    }
}

/* Return the k‑th prime among the d‑digit primes encoded in the
 * pre‑computed prime table (1‑based k).  d is guaranteed to be 1..6.
 */
static seq_t kth_preprime(int d, idx_t k)
{
    idx_t start_idx = prefix_counts[d - 1];
    return (seq_t)primes[start_idx + (size_t)(k - 1)];
}

/* Public sequence routine */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* safety, offset is 1 */
    init();

    /* handle digit lengths 1..6 using the pre‑computed data */
    size_t cum = 0;
    for (int d = 1; d <= 6; ++d) {
        size_t cnt_d = exact_counts[d];
        if (n <= cum + cnt_d) {
            idx_t k = n - cum;               /* 1‑based within this block */
            seq_t prime = kth_preprime(d, k);
            return (seq_t)d * pow10_arr[d] + prime;
        }
        cum += cnt_d;
    }

    /* n falls into the 7‑digit (or higher) range.  Generate primes on the fly. */
    size_t target = n - cum;              /* 1‑based index within this block */
    int d = 7;
    seq_t candidate = pow10_arr[d - 1];
    size_t cnt = 0;

    while (true) {
        if (isPrimeTrial(candidate)) {
            ++cnt;
            if (cnt == target) {
                return (seq_t)d * pow10_arr[d] + candidate;
            }
        }
        ++candidate;
        if (candidate > 2 && !(candidate & (seq_t)1)) {
            ++candidate; /* skip even numbers */
        }
        if (candidate >= pow10_arr[d]) {     /* move to next digit length */
            ++d;
            if (d > 9) break;                /* sequence defined only up to 9 digits */
            candidate = pow10_arr[d - 1];
            cnt = 0;
        }
    }
    return 0;  /* should never reach here for valid n */
}
